import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { appendAmpMessages } from "./ampTranscript.js";
import { ampTranscriptPath } from "./arming.js";
import { readTranscriptDelta } from "./transcriptReader.js";
const THREAD_ID = "T-amp-transcript";
function readLines() {
    return fs
        .readFileSync(ampTranscriptPath(THREAD_ID), "utf-8")
        .split("\n")
        .filter((line) => line.trim().length > 0)
        .map((line) => JSON.parse(line));
}
describe("appendAmpMessages", () => {
    let tempHome;
    const originalHome = process.env.HOME;
    beforeEach(() => {
        tempHome = fs.mkdtempSync(path.join(os.tmpdir(), "bitfab-amp-transcript-"));
        process.env.HOME = tempHome;
    });
    afterEach(() => {
        process.env.HOME = originalHome;
        fs.rmSync(tempHome, { recursive: true, force: true });
    });
    it("maps Amp roles onto the transcript roles the reader understands", () => {
        const messages = [
            { role: "user", id: 1, content: [{ type: "text", text: "hello" }] },
            {
                role: "assistant",
                id: 2,
                content: [{ type: "text", text: "hi back" }],
            },
            { role: "info", id: 3, content: [{ type: "text", text: "compacted" }] },
        ];
        appendAmpMessages(THREAD_ID, messages);
        expect(readLines().map((entry) => entry.message.role)).toEqual(["user", "assistant", "system"]);
    });
    it("rewrites tool results into the shape the summary reader expects", () => {
        appendAmpMessages(THREAD_ID, [
            {
                role: "user",
                id: 1,
                content: [
                    {
                        type: "tool_result",
                        toolUseID: "toolu_1",
                        output: "command output",
                        status: "done",
                    },
                ],
            },
        ]);
        const [entry] = readLines();
        const content = entry.message
            .content;
        expect(content[0]).toEqual({
            type: "tool_result",
            tool_use_id: "toolu_1",
            content: "command output",
            is_error: false,
        });
    });
    it("flags an errored tool result", () => {
        appendAmpMessages(THREAD_ID, [
            {
                role: "user",
                id: 1,
                content: [
                    {
                        type: "tool_result",
                        toolUseID: "toolu_1",
                        output: "boom",
                        status: "error",
                    },
                ],
            },
        ]);
        const content = readLines()[0].message.content;
        expect(content[0].is_error).toBe(true);
    });
    it("does not rewrite a message it has already written", () => {
        const first = {
            role: "user",
            id: "m1",
            content: [{ type: "text", text: "first" }],
        };
        const second = {
            role: "assistant",
            id: "m2",
            content: [{ type: "text", text: "second" }],
        };
        expect(appendAmpMessages(THREAD_ID, [first]).appendedMessages).toBe(1);
        expect(appendAmpMessages(THREAD_ID, [first, second]).appendedMessages).toBe(1);
        expect(readLines()).toHaveLength(2);
    });
    it("produces turns the shared transcript reader can parse", () => {
        appendAmpMessages(THREAD_ID, [
            {
                role: "user",
                id: 1,
                content: [{ type: "text", text: "do the thing" }],
            },
            {
                role: "assistant",
                id: 2,
                content: [
                    { type: "text", text: "on it" },
                    {
                        type: "tool_use",
                        id: "toolu_1",
                        name: "get_traces",
                        input: { limit: 5 },
                    },
                ],
            },
            {
                role: "user",
                id: 3,
                content: [
                    {
                        type: "tool_result",
                        toolUseID: "toolu_1",
                        output: "5 traces",
                        status: "done",
                    },
                ],
            },
        ]);
        const delta = readTranscriptDelta(ampTranscriptPath(THREAD_ID), 0);
        expect(delta.turns.map((turn) => turn.role)).toEqual([
            "user",
            "assistant",
            "tool_result",
        ]);
        expect(delta.turns[1].toolCalls).toEqual([
            {
                type: "tool_use",
                id: "toolu_1",
                name: "get_traces",
                input: { limit: 5 },
            },
        ]);
        expect(delta.newOffset).toBe(fs.statSync(ampTranscriptPath(THREAD_ID)).size);
    });
    it("keeps sequence numbers advancing across appends", () => {
        appendAmpMessages(THREAD_ID, [
            { role: "user", id: 1, content: [{ type: "text", text: "one" }] },
        ]);
        const first = readTranscriptDelta(ampTranscriptPath(THREAD_ID), 0);
        appendAmpMessages(THREAD_ID, [
            { role: "user", id: 2, content: [{ type: "text", text: "two" }] },
        ]);
        const second = readTranscriptDelta(ampTranscriptPath(THREAD_ID), first.newOffset, first.nextSequenceBase);
        expect(first.turns[0].sequence).toBe(0);
        expect(second.turns[0].sequence).toBe(1);
    });
});
